catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') {
        return;
    }
    // Obtém a data de hoje em formato 'YYYY-MM-DD'
    var today = new Date();
    today.setHours(0, 0, 0, 0); // Zera a hora da data de hoje
    var todayString = today.toISOString().split('T')[0]; // Formata para 'YYYY-MM-DD'

    // Obtém a data selecionada do campo 'expense_date'
    var selectedDate = newValue;

    // Compara as datas
    if (selectedDate > todayString) {
        g_form.addErrorMessage("You cannot insert a record with the current or future date! Please select a valid date.");
        g_form.setValue("expense_date", ""); // Limpa o campo de data
    } else if (selectedDate === todayString) {
        g_form.addErrorMessage("Oops! It looks like you've picked today's date. Please select a different date.");
        g_form.setValue("expense_date", ""); // Limpa o campo de data
    } else {
        g_form.clearMessages(); // Limpa mensagens de erro se houver
    }
}
